resources.afterResponseScript:
insomnia.test('Expected HTTP 201', () => insomnia.expect(insomnia.response.status).to.eql(201));
if (insomnia.response.status === 201) {
  insomnia.environment.set('conversation_id', insomnia.response.json().id);
  for (const key of ['last_request_id', 'last_message_text', 'confirmation_id', 'approval_request_id', 'approval_confirmation_id']) insomnia.environment.set(key, '');
}

insomnia.test('Expected HTTP 200', () => insomnia.expect(insomnia.response.status).to.eql(200));
if (insomnia.response.status === 200) {
  const history = insomnia.response.json();
  const pending = new Set(history.approvals.filter(a => a.status === 'pending').map(a => a.confirmationId));
  const parts = [...history.messages].reverse().flatMap(message => message.parts);
  const part = parts.find(p => p.type === 'data-address-approval'
    && p.data && pending.has(p.data.confirmationId) && Date.parse(p.data.expiresAt) > Date.now());
  insomnia.environment.set('confirmation_id', part ? part.data.confirmationId : '');
}

